#include <bits/stdc++.h>
using namespace std;

const int MD = 998244353;

long long power(long long base, int exp, int mod) {
    long long result = 1;
    long long cur = base % mod;
    while (exp > 0) {
        if (exp & 1) result = (result * cur) % mod;
        cur = (cur * cur) % mod;
        exp >>= 1;
    }
    return result;
}

long long modInverse(long long a, int m) {
    return power(a, m - 2, m);
}

long long ch(int n, int k, vector<long long>& ff, vector<long long>& gg, int mod) {
    return (ff[n] * gg[k] % mod) * gg[n - k] % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    int c = n - (int)k;
    vector<long long> ff(n + n + 1);
    vector<long long> gg(n + n + 1);
    long long f = 1;
    for (int i = 0; i <= n + n; i++) {
        ff[i] = f;
        gg[i] = modInverse(f, MD);
        f = (f * (i + 1)) % MD;
    }
    long long ans = 0;
    for (int a = 1; a <= c; a++) {
        long long x = (power(a, n, MD) * ch(c, a, ff, gg, MD)) % MD;
        if (a % 2 == 0) {
            ans += x;
        } else {
            ans -= x;
        }
    }
    ans = ((ans % MD) + MD) % MD;
    ans = (ans * ch(n, c, ff, gg, MD)) % MD;
    if (k > 0) {
        ans = (ans * 2) % MD;
    }
    cout << ans << "\n";
    return 0;
}
